import BufferView from '../../viewer.mjs'
import { encodeUTF8 } from '../../utils/strings.mjs'

export function parse (bytes) {
  const view = new BufferView(bytes)
  return {
    handlerType: view.getUint8(8, 4),
    name: view.getString(24, view.byteLength - 25, 'utf8')
  }
}

export function validate (value) {
  const { handlerType, name } = value
  if (!Array.isArray(handlerType) || handlerType.length !== 4 || handlerType.some(byte => byte < 0 || byte > 255)) {
    throw new Error('`handlerType` is invalid')
  }

  if (typeof name !== 'string') {
    throw new Error('`name` value is not a string')
  }
}

export function encode (value) {
  const { handlerType, name } = value
  const bytes = new Array(8).fill(0)
  bytes.push(...handlerType)
  bytes.push(...new Array(12).fill(0))

  const strBytes = encodeUTF8(name)
  bytes.push(...strBytes, 0)
  return bytes
}
